  "about_items": [
    {
      "n": "#162·26",
      "text": "This dark beige blazer is crafted from a soft wool-blend fabric, featuring a clean round neckline and a row of subtle buttons. Its relaxed fit drapes comfortably over your frame, creating a streamlined line that complements your X-shaped figure perfectly."
    },
    {
      "n": "#118·32",
      "text": "The matching beige sweater offers a comfortable, easy-fit silhouette with short sleeves and a fine knit texture. It sits neatly under the blazer, adding layers of warmth without bulk and highlighting your waist definition."
    },
    {
      "n": "#56·38",
      "text": "These beige palazzo trousers feature a distinctive front stitch detail and a relaxed, wide leg that flows effortlessly. The high waistband provides support while the cut accentuates your hips and elongates your legs."
    },
    {
      "n": "#40·36",
      "text": "The brown ankle boots are made of smooth leather with a thick platform sole and lace-up front. They provide excellent stability for standing all day in the office while maintaining a polished, professional appearance."
    },
    {
      "n": "#271·40",
      "text": "This mini-bag features a colorful geometric tapestry print with gold hardware accents and a wide woven strap. Its vibrant design serves as a cheerful focal point against the neutral tones of your outfit."
    }
  ]
